+func float16Number(bits uint16) float64 {
+	exponent := int((bits >> 10) & 31)
+	fraction := int(bits & 1023)
+	var value float64
+	switch exponent {
+	case 0:
+		value = math.Ldexp(float64(fraction), -24)
+	case 31:
+		value = math.Inf(1)
+		if fraction != 0 {
+			value = math.NaN()
+		}
+	default:
+		value = math.Ldexp(float64(1024+fraction), exponent-25)
+	}
+	if bits&0x8000 != 0 {
+		value = -value
+	}
+	return value
