183	// The bijection proves sharing and distinct identities separately from bytes.
184	type binaryID struct {
185		kind    reflect.Type
186		pointer uintptr
187		length  int
188	}
189	
190	func expectBinary(t testing.TB, expected, actual any) {
191		t.Helper()
192		forward := map[binaryID]binaryID{}
193		reverse := map[binaryID]binaryID{}
194		var visit func(any, any)
195		visit = func(e, a any) {
196			t.Helper()
197			if reflect.TypeOf(e) != reflect.TypeOf(a) {
198				t.Fatalf("binary type got %T want %T", a, e)
199			}
200			id := func(v any) binaryID {
201				rv := reflect.ValueOf(v)
202				length := 0
203				if rv.Kind() == reflect.Slice {
204					length = rv.Len()
205				}
206				return binaryID{rv.Type(), rv.Pointer(), length}
207			}
208			switch e.(type) {
209			case *Object, *TypedArray, *DataView, ArrayBuffer, []any:
210				ei, ai := id(e), id(a)
211				if previous, ok := forward[ei]; ok {
212					if previous != ai {
213						t.Fatal("shared identity lost")
214					}
215					return
216				}
217				if _, ok := reverse[ai]; ok {
218					t.Fatal("distinct identities collapsed")
219				}
220				forward[ei] = ai
221				reverse[ai] = ei
222			}
223			switch ev := e.(type) {
224			case *Object:
225				av := a.(*Object)
226				if ev.NullProto != av.NullProto || !reflect.DeepEqual(ev.Keys(), av.Keys()) {
227					t.Fatal("object metadata differs")
228				}
229				for _, key := range ev.Keys() {
230					x, _ := ev.Get(key)
231					y, _ := av.Get(key)
232					visit(x, y)
233				}
234			case []any:
235				av := a.([]any)
236				if len(ev) != len(av) {
237					t.Fatal("array length differs")
238				}
239				for i, x := range ev {
240					visit(x, av[i])
241				}
242			case ArrayBuffer:
243				if !bytes.Equal(ev, a.(ArrayBuffer)) {
244					t.Fatal("backing bytes differ")
245				}
246			case *TypedArray:
247				av := a.(*TypedArray)
248				if ev.Kind != av.Kind || ev.ByteOffset != av.ByteOffset || ev.ByteLength != av.ByteLength {
249					t.Fatal("typed view metadata differs")
250				}
251				visit(ev.Buffer, av.Buffer)
252				if !bytes.Equal(ev.Buffer[ev.ByteOffset:ev.ByteOffset+ev.ByteLength], av.Buffer[av.ByteOffset:av.ByteOffset+av.ByteLength]) {
253					t.Fatal("visible bytes differ")
254				}
255			case *DataView:
256				av := a.(*DataView)
257				if ev.ByteOffset != av.ByteOffset || ev.ByteLength != av.ByteLength {
258					t.Fatal("DataView metadata differs")
259				}
260				visit(ev.Buffer, av.Buffer)
261			default:
262				if !reflect.DeepEqual(e, a) {
263					t.Fatalf("binary value differs: got %v want %v", a, e)
264				}
265			}
266		}
267		visit(expected, actual)
268	}
