270	func checkBinaryDecode(t testing.TB, name, wire string) {
271		t.Helper()
272		identity := func(v any) (any, error) { return v, nil }
273		if name == "reduced_buffer" {
274			if _, err := Parse(wire, map[string]func(any) (any, error){"Raw": identity}); err == nil {
275				t.Fatal("custom raw-buffer slot admitted")
276			}
277			return
278		}
279		if name == "reduced_view" {
280			v, err := Parse(wire, map[string]func(any) (any, error){"View": identity})
281			if err != nil || v != "payload" {
282				t.Fatalf("view override: %v %v", v, err)
283			}
284			return
285		}
286		actual, err := Parse(wire, nil)
287		if err != nil {
288			t.Fatal(err)
289		}
290		expectBinary(t, binaryValue(t, name), actual)
291	}
